package lk.smartroute.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;
import lk.smartroute.dto.ApiDtos.*;import lk.smartroute.dto.DtoMapper;import lk.smartroute.dto.WalletDtos.*;
import lk.smartroute.event.BookingPaymentCompletedEvent;
import lk.smartroute.exception.*;import lk.smartroute.model.*;import lk.smartroute.repository.*;import lk.smartroute.service.*;
import org.springframework.data.domain.Pageable;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import org.springframework.context.ApplicationEventPublisher;
import java.math.*;import java.time.*;import java.util.*;
@Service @Transactional
public class WalletServiceImpl implements WalletService{
 private final WalletRepository wallets;private final WalletTransactionRepository txs;private final CustomerCardRepository cards;private final UserRepository users;private final BookingRepository bookings;private final PaymentRepository payments;private final OtpService otps;private final ObjectMapper json;private final NotificationService notifications;private final ApplicationEventPublisher events;
 public WalletServiceImpl(WalletRepository wallets,WalletTransactionRepository txs,CustomerCardRepository cards,UserRepository users,BookingRepository bookings,PaymentRepository payments,OtpService otps,ObjectMapper json,NotificationService notifications,ApplicationEventPublisher events){this.wallets=wallets;this.txs=txs;this.cards=cards;this.users=users;this.bookings=bookings;this.payments=payments;this.otps=otps;this.json=json;this.notifications=notifications;this.events=events;}
 public WalletResponse getWallet(String email){return new WalletResponse(wallet(email).getBalance());}
 @Transactional(readOnly=true) public PageResponse<WalletTransactionResponse> transactions(String email,Pageable p){return PageResponse.from(txs.findByWalletUserEmailIgnoreCaseOrderByCreatedAtDesc(email,p).map(this::dto));}
 @Transactional(readOnly=true) public List<CardResponse> cards(String email){return cards.findByUserEmailIgnoreCaseOrderByCreatedAtDesc(email).stream().map(this::dto).toList();}
 public CardResponse addCard(String email,CardVerificationRequest r){CardPayload p=validateCard(r);CustomerCard c=new CustomerCard();User u=user(email);c.setUser(u);c.setCardholderName(p.cardholderName());c.setBrand(p.brand());c.setLastFour(p.lastFour());c.setExpiryMonth(p.expiryMonth());c.setExpiryYear(p.expiryYear());c.setCardToken(p.token());c.setVerified(true);c=cards.save(c);notifications.sendSecurityNotification(u,NotificationType.CARD_ADDED,"Saved card added","A saved card ending "+p.lastFour()+" was added to your account.","CARD-ADDED:"+c.getId());return dto(c);}
 public OtpChallengeResponse requestCardOtp(String email,CardVerificationRequest r){User u=user(email);CardPayload p=validateCard(r);String key="CARD-"+UUID.randomUUID();try{String payload=json.writeValueAsString(Map.of("cardholderName",p.cardholderName(),"brand",p.brand().name(),"lastFour",p.lastFour(),"expiryMonth",p.expiryMonth(),"expiryYear",p.expiryYear(),"token",p.token()));var o=otps.issue(u,email,OtpPurpose.CARD_VERIFICATION,key,payload,false);return new OtpChallengeResponse(key,"Verification code sent to your registered email",o.getExpiresAt());}catch(Exception e){if(e instanceof RuntimeException re)throw re;throw new IllegalStateException("Unable to prepare card verification");}}
 public CardResponse verifyCard(String email,OtpVerifyRequest r){var o=otps.verifyAndConsume(email,OtpPurpose.CARD_VERIFICATION,r.operationKey(),r.otp());try{var n=json.readTree(o.getPayloadJson());User u=user(email);CustomerCard c=new CustomerCard();c.setUser(u);c.setCardholderName(n.get("cardholderName").asText());c.setBrand(CardBrand.valueOf(n.get("brand").asText()));c.setLastFour(n.get("lastFour").asText());c.setExpiryMonth(n.get("expiryMonth").asInt());c.setExpiryYear(n.get("expiryYear").asInt());c.setCardToken(n.get("token").asText());c.setVerified(true);c=cards.save(c);notifications.sendSecurityNotification(u,NotificationType.CARD_ADDED,"Saved card added","A saved card ending "+c.getLastFour()+" was added to your account.","CARD-ADDED:"+c.getId());return dto(c);}catch(Exception e){if(e instanceof RuntimeException re)throw re;throw new IllegalStateException("Unable to save card");}}
 public void removeCard(String email,Long id){CustomerCard c=cards.findByIdAndUserEmailIgnoreCase(id,email).orElseThrow(()->new ResourceNotFoundException("Card not found"));String lastFour=c.getLastFour();User u=c.getUser();cards.delete(c);notifications.sendSecurityNotification(u,NotificationType.CARD_REMOVED,"Saved card removed","A saved card ending "+lastFour+" was removed from your account.","CARD-REMOVED:"+id);}
 public OtpChallengeResponse requestTopUpOtp(String email,TopUpRequest r){CustomerCard c=cards.findByIdAndUserEmailIgnoreCase(r.cardId(),email).orElseThrow(()->new ResourceNotFoundException("Card not found"));if(!c.isVerified())throw new IllegalStateException("Card is not verified");BigDecimal amount=money(r.amount());if(amount.compareTo(new BigDecimal("100.00"))<0||amount.compareTo(new BigDecimal("50000.00"))>0)throw new IllegalArgumentException("Top-up amount must be between Rs. 100 and Rs. 50,000");String key="TOPUP-"+UUID.randomUUID();try{String payload=json.writeValueAsString(Map.of("cardId",c.getId(),"amount",amount));var o=otps.issue(user(email),email,OtpPurpose.WALLET_TOP_UP,key,payload,false);return new OtpChallengeResponse(key,"Verification code sent to your registered email",o.getExpiresAt());}catch(Exception e){if(e instanceof RuntimeException re)throw re;throw new IllegalStateException("Unable to prepare top-up");}}
 public TopUpResponse confirmTopUp(String email,OtpVerifyRequest r){var o=otps.verifyAndConsume(email,OtpPurpose.WALLET_TOP_UP,r.operationKey(),r.otp());try{var n=json.readTree(o.getPayloadJson());Long cardId=n.get("cardId").asLong();BigDecimal amount=money(new BigDecimal(n.get("amount").asText()));CustomerCard c=cards.findByIdAndUserEmailIgnoreCase(cardId,email).orElseThrow(()->new ResourceNotFoundException("Card not found"));Wallet w=walletForUpdate(email);w.setBalance(w.getBalance().add(amount));WalletTransaction t=transaction(w,null,c,WalletTransactionType.TOP_UP,amount,w.getBalance(),null);t=txs.save(t);notifications.sendWalletNotification(t);return new TopUpResponse(w.getBalance(),dto(t));}catch(Exception e){if(e instanceof RuntimeException re)throw re;throw new IllegalStateException("Unable to complete top-up");}}
 public WalletPaymentResponse payBooking(String email,Long bookingId){Wallet w=walletForUpdate(email);Booking b=bookings.findByIdForUpdate(bookingId).orElseThrow(()->new ResourceNotFoundException("Booking not found"));if(!b.getPassenger().getUser().getEmail().equalsIgnoreCase(email))throw new ForbiddenActionException("Booking does not belong to user");if(b.getBookingStatus()!=BookingStatus.PENDING_PAYMENT)throw new IllegalStateException("Booking cannot be paid in its current status");if(txs.findByBookingIdAndTransactionType(bookingId,WalletTransactionType.BOOKING_PAYMENT).isPresent())throw new ConflictException("Booking has already been charged to a wallet");BigDecimal amount=money(b.getTotalAmount());if(w.getBalance().compareTo(amount)<0)throw new IllegalStateException("Insufficient wallet balance");w.setBalance(w.getBalance().subtract(amount));if(w.getBalance().signum()<0)throw new IllegalStateException("Insufficient wallet balance");WalletTransaction t=transaction(w,b,null,WalletTransactionType.BOOKING_PAYMENT,amount,w.getBalance(),null);t=txs.saveAndFlush(t);Payment p=new Payment();p.setBooking(b);p.setPaymentMethod("SMARTROUTE_WALLET");p.setTransactionReference(t.getTransactionReference());p.setPaymentDate(LocalDateTime.now());p.setAmount(amount);p.setPaymentStatus(PaymentStatus.SUCCESS);p=payments.saveAndFlush(p);b.setBookingStatus(BookingStatus.CONFIRMED);b.setPaymentDueAt(null);events.publishEvent(new BookingPaymentCompletedEvent(b.getId(),p.getId(),t.getId(),true));return new WalletPaymentResponse(DtoMapper.payment(p),w.getBalance());}
 public void refundWalletPayment(Long bookingId,BigDecimal requested){var opt=txs.findByBookingIdAndTransactionType(bookingId,WalletTransactionType.BOOKING_PAYMENT);if(opt.isEmpty())return;WalletTransaction original=opt.get();if(original.getStatus()==WalletTransactionStatus.REFUNDED)return;Wallet w=wallets.findByIdForUpdate(original.getWallet().getId()).orElseThrow();Booking b=bookings.findByIdForUpdate(bookingId).orElseThrow();if(txs.findByBookingIdAndTransactionType(bookingId,WalletTransactionType.REFUND).isPresent())return;BigDecimal amount=requested==null?original.getAmount():requested.setScale(2,RoundingMode.HALF_UP);if(amount.signum()<0||amount.compareTo(original.getAmount())>0)throw new IllegalArgumentException("Invalid refund amount");w.setBalance(w.getBalance().add(amount));WalletTransaction refund=transaction(w,b,null,WalletTransactionType.REFUND,amount,w.getBalance(),original.getTransactionReference());refund=txs.save(refund);original.setStatus(WalletTransactionStatus.REFUNDED);notifications.sendWalletNotification(refund);payments.findByTransactionReference(original.getTransactionReference()).ifPresent(p->p.setPaymentStatus(PaymentStatus.REFUNDED));}
 private Wallet transactionWallet(String email){return wallet(email);} private Wallet wallet(String email){return wallets.findByUserEmailIgnoreCase(email).orElseGet(()->{Wallet w=new Wallet();w.setUser(user(email));w.setBalance(BigDecimal.ZERO);return wallets.save(w);});}
 private Wallet walletForUpdate(String email){wallet(email);return wallets.findByEmailForUpdate(email).orElseThrow();}
 private User user(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->new ResourceNotFoundException("User not found"));}
 private WalletTransaction transaction(Wallet w,Booking b,CustomerCard c,WalletTransactionType type,BigDecimal amount,BigDecimal after,String related){WalletTransaction t=new WalletTransaction();t.setWallet(w);t.setBooking(b);t.setCard(c);t.setTransactionType(type);t.setStatus(WalletTransactionStatus.SUCCESS);t.setAmount(amount);t.setBalanceAfter(after);t.setRelatedReference(related);t.setTransactionReference("WAL-"+UUID.randomUUID().toString().replace("-","").toUpperCase());return t;}
 private WalletTransactionResponse dto(WalletTransaction t){return new WalletTransactionResponse(t.getId(),t.getTransactionReference(),t.getTransactionType(),t.getStatus(),t.getAmount(),t.getBalanceAfter(),t.getBooking()==null?null:t.getBooking().getId(),t.getCreatedAt());}
 private CardResponse dto(CustomerCard c){return new CardResponse(c.getId(),c.getCardholderName(),c.getBrand(),"**** **** **** "+c.getLastFour(),c.getExpiryMonth(),c.getExpiryYear(),c.isVerified());}
 private CardPayload validateCard(CardVerificationRequest r){String number=r.cardNumber().replaceAll("\\s","");if(!luhn(number))throw new IllegalArgumentException("Invalid card number");CardBrand inferredBrand=brand(number);if(r.brand()!=null&&r.brand()!=inferredBrand)throw new IllegalArgumentException("Selected card brand does not match the card number");if(r.expiryMonth()<1||r.expiryMonth()>12)throw new IllegalArgumentException("Invalid expiry month");YearMonth exp=YearMonth.of(r.expiryYear(),r.expiryMonth());if(exp.isBefore(YearMonth.now()))throw new IllegalArgumentException("Card has expired");if("4000000000000002".equals(number))throw new IllegalStateException("Simulated card was declined");return new CardPayload(r.cardholderName().trim(),inferredBrand,number.substring(number.length()-4),r.expiryMonth(),r.expiryYear(),"SIM-"+UUID.randomUUID());}
 private record CardPayload(String cardholderName,CardBrand brand,String lastFour,int expiryMonth,int expiryYear,String token){}
 private BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);}
 private CardBrand brand(String n){if(n.startsWith("4"))return CardBrand.VISA;if(n.matches("5[1-5].*")||(n.length()>=4&&Integer.parseInt(n.substring(0,4))>=2221&&Integer.parseInt(n.substring(0,4))<=2720))return CardBrand.MASTERCARD;throw new IllegalArgumentException("Only Visa and Mastercard are supported in this simulation");}
 private boolean luhn(String n){int sum=0;boolean alt=false;for(int i=n.length()-1;i>=0;i--){int d=n.charAt(i)-'0';if(alt){d*=2;if(d>9)d-=9;}sum+=d;alt=!alt;}return sum%10==0;}
}
